/// <summary>
/// Data provider for the Report parameter case report.
/// Extends <c>SrsReportDataProviderBase</c> and populates the <c>ConDemoRptParamTmp</c> temporary table.
/// </summary>
[
    SRSReportParameterAttribute(classStr(ConDemoRptParamContract))
]
public class ConDemoRptParamDP extends SrsReportDataProviderBase
{
    ConDemoRptParamTmp conDemoRptParamTmp;

}

