/// <summary>
/// Returns the temporary table buffer used by the report dataset.
/// </summary>
/// <returns>The <c>ConDemoRptParamTmp</c> table buffer.</returns>
[SRSReportDataSetAttribute(tableStr(ConDemoRptParamTmp))]
public ConDemoRptParamTmp getConDemoRptParamTmp()
{
    select conDemoRptParamTmp;
    return conDemoRptParamTmp;
}

